import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    static int lowerBound(long[] a, long v) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] segs = new long[(int) n][2];
        for (int i = 0; i < segs.length; i++) {
            for (int j = 0; j < segs[i].length; j++) {
                segs[i][j] = Long.parseLong(next());
            }
        }

        int cnt = (int) n;
        long big = 1000000000L;
        long[] keys = new long[cnt];
        long[] ends = new long[cnt];
        for (int i = 0; i < cnt; i++) {
            keys[i] = (segs[i][0] << 30) | (big - segs[i][1]);
            ends[i] = segs[i][1];
        }
        Arrays.sort(keys);
        Arrays.sort(ends);
        int m = 0;
        for (int i = 0; i < cnt; i++) {
            if (i == 0 || ends[i] != ends[i - 1]) ends[m++] = ends[i];
        }
        long[] uniq = Arrays.copyOf(ends, m);
        long[] t = new long[m + 1];
        long total = 0;
        for (int c = 0; c < cnt; c++) {
            long r = big - (keys[c] & ((1L << 30) - 1));
            int e = lowerBound(uniq, r) + 1;
            total += c - bitSum(t, e - 1);
            bitAdd(t, e, 1);
        }
        System.out.println(total);
    }
}
